import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long[] vals = Arrays.stream(br.readLine().split(" ")).mapToLong(Long::parseLong).toArray();
        if (vals[0] > vals[1]) {
            vals[0] ^= vals[1];
            vals[1] ^= vals[0];
            vals[0] ^= vals[1];
        }
        System.out.println(calculate(vals[0], vals[1]));
    }

    static long calculate(long x, long y) {
        if (y < 3) {
            return 0;
        }
        if (x == 1) {
            return y - adjust(y % 6);
        }
        if (x == 2) {
            if (y == 3) {
                return 4;
            }
            if (y == 7) {
                return 12;
            }
            return x * y;
        }
        if (x == 3) {
            long answer = x * y;
            if (y % 2 == 1) {
                answer--;
            }
            return answer;
        }
        long answer = x * y;
        if (x % 2 == 1 && y % 2 == 1) {
            answer--;
        }
        return answer;
    }

    static long adjust(long remainder) {
        return remainder > 3 ? 6 - remainder : remainder;
    }
}
